questionvariables.text:
/* Design: area under a positive curve. [c0, c1, c2, c3, lo, hi]; every curve is positive on [lo, hi]. Source: adapted from SMP AS/A2 Core 1, chapter 11, Exercise C questions 1 and 6. */
L: [[4,-2,9,0,2,3],[2,6,3,0,2,4],[6,6,3,0,2,4],[2,-2,3,0,2,4],[8,0,3,0,1,2],[3,-1,0,1,1,2],[3,-1,0,1,1,3],[6,0,0,1,1,2],[1,2,0,1,1,4],[4,3,0,1,2,4]];
ix: 1+rand(10);
cc0: L[ix][1]; cc1: L[ix][2]; cc2: L[ix][3]; cc3: L[ix][4]; lo: L[ix][5]; hi: L[ix][6];
fx: cc0+cc1*x+cc2*x^2+cc3*x^3;
Fx: integrate(fx,x);
Fhi: subst(x=hi,Fx); Flo: subst(x=lo,Fx);
A: Fhi-Flo;
/* diagnostics */
upper: Fhi;
intg: subst(x=hi,fx)-subst(x=lo,fx);
neg: -A;
/* board: bounding box from the variant */
ymx: lmax(makelist(subst(x=lo-1/2+j*(hi-lo+1)/20,fx),j,0,20));
bxl: float(min(-0.5,lo-1)); bxr: float(hi+1); byt: float(1.15*ymx); byb: float(-0.24*ymx);
